    if not pattern: return 0
    lps = [0]*len(pattern)
    k = 0
    for i in range(1, len(pattern)):
        while k and pattern[k] != pattern[i]:
            k = lps[k-1]
        if pattern[k] == pattern[i]:
            k += 1
        lps[i] = k
    k = 0
    for i, c in enumerate(text):
        while k and pattern[k] != c:
            k = lps[k-1]
